use std::io;

fn gcd(a: i32, b: i32) -> i32 {
    let mut tmp;
    let mut s = a;
    let mut t = b;

    while t != 0 {
        tmp = s % t;
        (s, t) = (t, tmp);
    }

    s
}

fn main() {
    println!("{}", gcd(252, 105));
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        return false
    }
    let mut i = 2
    while i * i <= n {
        if n % i == 0 {
            return false
        }
        i = i + 1
    }
    true
}

