fn range(a: Int, b: Int) -> Option<Int> {
    if a < b {
        Some(a)
    } else {
        None
    }
}

fn last(v: Vec<Int>) -> Option<Int> {
    if len(v) > 0 {
        Some(v.get(len(v) - 1)?)
    } else {
        None
    }
}

